SELECT time, CAST(metric_0001 AS DOUBLE PRECISION) AS metric_0001, CAST(metric_0455 AS DOUBLE PRECISION) AS metric_0455, CAST(metric_0910 AS DOUBLE PRECISION) AS metric_0910, CAST(metric_1365 AS DOUBLE PRECISION) AS metric_1365, CAST(metric_1820 AS DOUBLE PRECISION) AS metric_1820, CAST(metric_2274 AS DOUBLE PRECISION) AS metric_2274, CAST(metric_2729 AS DOUBLE PRECISION) AS metric_2729, CAST(metric_3184 AS DOUBLE PRECISION) AS metric_3184, CAST(metric_3639 AS DOUBLE PRECISION) AS metric_3639, CAST(metric_4094 AS DOUBLE PRECISION) AS metric_4094 FROM wide4094 PREWHERE time >= '2024-09-23' AND time < '2025-01-01' ORDER BY time
